t.script:
document.addEventListener('DOMContentLoaded', function () {
    var master = document.getElementById('kx_pickup_select_all');
    if (!master) {
        return;
    }
    master.addEventListener('change', function () {
        document.querySelectorAll('.kx-pickup-select').forEach(function (box) {
            box.checked = master.checked;
        });
    });
});

function kxConfirmShipmentBulk(button, message) {
    var selected = document.querySelectorAll('.kx-shipment-select:checked');
    if (!selected.length) {
        window.alert('Select at least one shipment.');
        return false;
    }
    return window.confirm(message + ' (' + selected.length + ')');
}
document.addEventListener('DOMContentLoaded', function () {
    var master = document.getElementById('kx_shipment_select_all');
    if (!master) {
        return;
    }
    master.addEventListener('change', function () {
        document.querySelectorAll('.kx-shipment-select').forEach(function (box) {
            box.checked = master.checked;
        });
    });
});
